delta = {"q0": {"0": "q1", "1": "q0"},
         "q1": {"0": "q1", "1": "q2"},
         "q2": {"0": "q1", "1": "q0"}}
def accepts(text):
    if any(ch not in {"0", "1"} for ch in text):
        raise ValueError("Use only 0 and 1")
    state = "q0"
    for ch in text:
        state = delta[state][ch]
    return state == "q2"

