marking = {'ready': 1, 'working': 0}
def fire(source, target):
    if marking[source] < 1:
        return False
    marking[source] -= 1
    marking[target] += 1
    return True
print(fire('ready', 'working'))  # True
print(fire('ready', 'working'))  # False
print(marking)  # {'ready': 0, 'working': 1}

CODE = (3, 1, 4, 1)
def run_keypad(inputs):
    k = 0
    for digit in inputs:
        if k == len(CODE):
            break
        k = k + 1 if digit == CODE[k] else 0
    return k == len(CODE)
print(run_keypad([3, 1, 9, 3, 1, 4, 1]))  # True
